"""GitHub hosts downloads/help; both extensions run exclusively on localhost."""
from pathlib import Path
import argparse,json,shutil
root=Path(__file__).resolve().parent.parent
parser=argparse.ArgumentParser();parser.add_argument('--dest',default='work/pages24');args=parser.parse_args();target=(root/args.dest).resolve();assert target!=root and target.is_relative_to(root);target.mkdir(parents=True,exist_ok=True)
source=root/'outputs/owlbear';local='http://localhost:17632/'
for name in ['manifest.json','tools-manifest.json']:
 m=json.loads((source/name).read_text(encoding='utf8'));m['name']+='（本地）';m['icon']=local+m['icon'].lstrip('/');m['background_url']=local+m['background_url'].lstrip('/')
 for key in ['icon','popover']:m['action'][key]=local+m['action'][key].lstrip('/')
 (target/name).write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n',encoding='utf8',newline='\n')
shutil.copyfile(source/'icon.svg',target/'icon.svg')
(target/'.nojekyll').write_text('',encoding='utf8')
(target/'index.html').write_text('''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>旅人手札 · 本地枭熊插件</title><style>*{box-sizing:border-box}body{margin:40px auto;padding:0 20px;max-width:800px;background:#211b17;color:#f5e7cb;font:600 16px/1.8 "Microsoft YaHei",sans-serif}h1{font-size:30px}section{margin:20px 0;padding:22px;background:#2b241e;border:1px solid #695136;border-radius:12px}a{color:#f0c582}input{display:block;width:100%;padding:12px;margin:7px 0;font:600 14px monospace;border:1px solid #81633d;background:#171410;color:#fff0d0;border-radius:6px}button{padding:10px 14px;background:#a87c3e;color:#fff4df;border:0;border-radius:6px;cursor:pointer}small{color:#c9b798}</style><body><small>TRAVELER FOLIO · v0.25.0</small><h1>全部功能统一到本地插件</h1><p>角色小卡、动画骰、先攻、演出、怪物图鉴和生命速调，随旅人手札 EXE 一起更新。</p><section><h2>安装</h2><ol><li>每位玩家先打开新版旅人手札 EXE，再进入枭熊房间。</li><li>DM 安装下面两个本地地址，并在房间启用；停用旧的线上扩展，避免重复。</li><li>更新手札后重新打开 EXE 并刷新房间，两个插件一起加载新版。</li></ol><label>角色速查<input id="card" readonly value="http://localhost:17632/manifest.json"></label><button data-copy="card">复制角色速查地址</button><label>跑团工具<input id="tools" readonly value="http://localhost:17632/tools-manifest.json"></label><button data-copy="tools">复制跑团工具地址</button><p id="notice" role="status"></p></section><section><h2>更新与资料</h2><p>GitHub 提供 EXE、APK、离线 HTML、源码与签名更新清单；插件代码和角色、图鉴资料都从自己的电脑读取。</p><p><a href="https://github.com/Feathercatttt/traveler-folio/releases/latest">下载最新版本</a> · <a href="https://github.com/Feathercatttt/traveler-folio/blob/main/docs/v0.25安装与使用方法.md">功能与使用说明</a></p></section><p><small>AI 辅助生成和维护的代码。旧的 GitHub 安装地址仅用于兼容迁移，指向同一套本地插件；没有另行维护的线上功能版本。</small></p><script>document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const input=document.getElementById(b.dataset.copy);try{await navigator.clipboard.writeText(input.value);document.getElementById('notice').textContent='已复制';}catch{input.focus();input.select();}});</script></body></html>''',encoding='utf8',newline='\n')
print('Built local-extension installation page',target)
